<?php
namespace App\Tests\Runtime;
use App\Runtime\RuntimePurchasePaymentAudit;
use PHPUnit\Framework\TestCase;
final class RuntimePurchasePaymentAuditTest extends TestCase
{
    public static function definition(): array { return ['entityCode'=>'proc_compra_pagamentos_progress','primaryKey'=>'pagamento_key','apiBinding'=>['sourceCode'=>'motor_progress_ciw_cadastros'],'apiSource'=>['responseContract'=>'sursum-programs']]; }
    public static function endpoint(string $op): array { return ['method'=>'POST','url'=>'http://127.0.0.1:19910/med/web/SursumPrograms/ciw-cadastros','bodyTemplate'=>['resource'=>'proc_compra_pagamentos','operation'=>$op]]; }
    public static function key(int $parent=17,int $title=7): string { $p=static fn($s)=>'V'.mb_strlen((string)$s).':'.$s; return 'p_'.strtoupper(hash('sha256',$p($parent).$p('505').$p($title))); }
    public static function row(int $title=7): array { return ['pagamento_key'=>self::key(17,$title),'proc_compra_id'=>17,'titulos'=>[$title],'num_id_tit_ap'=>$title,'empresa_id'=>5,'cod_empresa'=>'500','cod_estab'=>'505','cod_espec_docto'=>'ANT','cod_ser_docto'=>'','cdn_fornecedor'=>8,'cod_tit_ap'=>'T7','cod_parcela'=>'01','dat_emis_docto'=>'2026-10-22','dat_vencto_tit_ap'=>null,'cod_indic_econ'=>'0','val_origin_tit_ap'=>150,'valor_real'=>150,'valor_dolar'=>30]; }
    public static function ledger(int $id=91,int $title=7,int $action=1): array { return ['cta_corren_fornec_imp_id'=>$id,'fornecedor_id'=>8,'data'=>'2026-10-22','item_proc_compra_id'=>11,'historico'=>'teste','cod_tipo_movto'=>4,'vl_lancto'=>30,'cod_acao'=>$action,'login'=>'real-user','data_hora'=>'2026-10-22T12:00:00.123','num_id_tit_ap'=>$title,'item_container_id'=>0,'transacao_id'=>0,'proc_compra_id'=>17]; }
    public static function body(string $op='create'): array {
        $row=self::row();$link=['resource'=>'purchase_payment_links','operation'=>$op,'recordId'=>self::key(),'before'=>$op==='create'?[]:$row,'after'=>$op==='delete'?[]:$row];
        return ['success'=>true,'committed'=>true,'data'=>$row,'audit'=>['version'=>1,'source'=>'progress-transaction','resource'=>'proc-compra-pagamentos','operation'=>$op,'recordId'=>self::key(),'proc_compra_id'=>17,'before'=>$link['before'],'after'=>$link['after'],'actor'=>['login'=>'real-user'],'warnings'=>[],'changes'=>[$link,['resource'=>'cta_corren_fornec_imp','operation'=>'create','recordId'=>91,'before'=>[],'after'=>self::ledger(91,7,$op==='create'?1:3)]]]];
    }
    private function inspect(array $body,string $op='create',mixed $parent=17,?array $d=null,?array $e=null,?string $actor='real-user'): array { return RuntimePurchasePaymentAudit::inspect($d??self::definition(),$e??self::endpoint($op),$body,$op,self::key(),$parent,$actor); }
    public function testImportsFullImagesAndRelatedLedgerWithVerifiedPurchaseAndPaymentIdentity(): void {
        foreach(['create','delete'] as $op){$b=self::body($op);$r=$this->inspect($b,$op);self::assertTrue($r['metadata']['available']);self::assertSame($b['audit']['before'],$r['before']);self::assertSame($b['audit']['after'],$r['after']);self::assertCount(1,$r['events']);self::assertSame($b['audit']['changes'][1]['after'],$r['events'][0]['after']);foreach([$r['metadata'],$r['events'][0]['metadata']] as $m){self::assertSame(17,$m['procCompraId']);self::assertSame(self::key(),$m['paymentKey']);}}
    }
    public function testBulkCreatesImportEachLinkAndOnlyLedgersProvenByThoseTitles(): void {
        $b=self::body();$row=self::row(8);$b['audit']['changes'][]=['resource'=>'purchase_payment_links','operation'=>'create','recordId'=>self::key(17,8),'before'=>[],'after'=>$row];$b['audit']['changes'][]=['resource'=>'cta_corren_fornec_imp','operation'=>'create','recordId'=>92,'before'=>[],'after'=>self::ledger(92,8)];$r=$this->inspect($b);self::assertTrue($r['metadata']['available']);self::assertCount(3,$r['events']);self::assertSame(self::key(17,8),$r['events'][1]['metadata']['paymentKey']);self::assertSame(self::key(17,8),$r['events'][2]['metadata']['paymentKey']);
    }
    public function testRejectsPartialSpoofedOrCrossPurchaseEvidenceWithoutLeakingAnyImages(): void {
        foreach(['commit','success','source','resource','parent','parent-type','actor','actor-shape','actor-empty','key','key-row','field-missing','field-extra','date','numeric','id-zero','ledger-parent','ledger-title','ledger-login','ledger-type','ledger-action','ledger-container','ledger-extra','ledger-missing','duplicate','no-main','main-diverges','warnings','changes-empty'] as $case){$b=self::body();switch($case){
            case 'commit':$b['committed']=false;break;case 'success':$b['success']=false;break;case 'source':$b['audit']['source']='browser';break;case 'resource':$b['audit']['resource']='container-pagamentos';break;case 'parent':$b['audit']['proc_compra_id']=18;break;case 'parent-type':$b['audit']['proc_compra_id']='17';break;case 'actor':$b['audit']['actor']['login']='forged';break;case 'actor-shape':$b['audit']['actor']['id']=1;break;case 'actor-empty':$b['audit']['actor']['login']='';break;case 'key':$b['audit']['recordId']='p_'.str_repeat('A',64);break;case 'key-row':$b['audit']['after']['pagamento_key']=self::key(18);break;case 'field-missing':unset($b['audit']['after']['valor_real']);break;case 'field-extra':$b['audit']['after']['container_id']=17;break;case 'date':$b['audit']['after']['dat_emis_docto']='2026-02-30';break;case 'numeric':$b['audit']['after']['valor_real']='150';break;case 'id-zero':$b['audit']['after']['empresa_id']=0;break;case 'ledger-parent':$b['audit']['changes'][1]['after']['proc_compra_id']=18;break;case 'ledger-title':$b['audit']['changes'][1]['after']['num_id_tit_ap']=8;break;case 'ledger-login':$b['audit']['changes'][1]['after']['login']='forged';break;case 'ledger-type':$b['audit']['changes'][1]['after']['cod_tipo_movto']=5;break;case 'ledger-action':$b['audit']['changes'][1]['after']['cod_acao']=2;break;case 'ledger-container':$b['audit']['changes'][1]['after']['item_container_id']=1;break;case 'ledger-extra':$b['audit']['changes'][1]['after']['container_id']=17;break;case 'ledger-missing':unset($b['audit']['changes'][1]['after']['data']);break;case 'duplicate':$b['audit']['changes'][]=$b['audit']['changes'][1];break;case 'no-main':array_shift($b['audit']['changes']);break;case 'main-diverges':$b['audit']['changes'][0]['after']['valor_real']=151;break;case 'warnings':$b['audit']['warnings']=['x'=>true];break;case 'changes-empty':$b['audit']['changes']=[];break;
        }$r=$this->inspect($b);self::assertFalse($r['metadata']['available'],$case);self::assertSame([],$r['before'],$case);self::assertSame([],$r['after'],$case);self::assertSame([],$r['events'],$case);}
        self::assertFalse($this->inspect(self::body(),parent:18)['metadata']['available']);self::assertFalse($this->inspect(self::body(),parent:null)['metadata']['available']);self::assertFalse($this->inspect(self::body(),actor:null)['metadata']['available']);
    }
    public function testClosesRegisteredSourceRouteOperationAndPrimaryKey(): void {
        foreach([['entityCode'=>'other'],['primaryKey'=>'num_id_tit_ap'],['apiBinding'=>['sourceCode'=>'other']],['apiSource'=>['responseContract'=>'generic']]] as $delta){self::assertFalse($this->inspect(self::body(),d:array_replace_recursive(self::definition(),$delta))['metadata']['available']);}
        foreach([['url'=>'https://evil.test/SursumPrograms/ciw-cadastros'],['url'=>'http://127.0.0.1:19910/SursumPrograms/other'],['method'=>'GET'],['bodyTemplate'=>['resource'=>'proc_compra_pagamentos','operation'=>'update']],['bodyTemplate'=>['resource'=>'proc_compra_pagamentos','operation'=>'create','extra'=>1]]] as $delta){self::assertFalse($this->inspect(self::body(),e:array_replace(self::endpoint('create'),$delta))['metadata']['available']);}
    }
    public function testLedgerActionFollowsItsPhysicalSignRuleAndNotTheLinkOperation(): void {
        foreach(['create','delete'] as $op){$b=self::body($op);$b['audit']['changes'][1]['after']['cod_acao']=$op==='create'?3:1;self::assertTrue($this->inspect($b,$op)['metadata']['available']);}
    }
    public function testRejectsOversizedConfirmedTransactionsInsteadOfPartialImport(): void {
        $b=self::body();$b['audit']['changes']=[$b['audit']['changes'][0]];foreach(range(1,2000) as $id){$b['audit']['changes'][]=['resource'=>'cta_corren_fornec_imp','operation'=>'create','recordId'=>$id,'before'=>[],'after'=>self::ledger($id)];}self::assertFalse($this->inspect($b)['metadata']['available']);
        $b=self::body();$b['audit']['changes']=[];foreach(range(7,107) as $title){$b['audit']['changes'][]=['resource'=>'purchase_payment_links','operation'=>'create','recordId'=>self::key(17,$title),'before'=>[],'after'=>self::row($title)];}self::assertFalse($this->inspect($b)['metadata']['available']);
    }
}


